package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.MethodOrderer;
import org.junit.jupiter.api.Order;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestMethodOrder;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test — ECGI 관리
 *
 * @target-controller ECGIController (/web/admin/ecgis)
 * Endpoints: GET /ajax, POST /, DELETE /{ecgiSeqs}, GET /excel, GET /sample
 *
 * NOTE: POST /web/admin/ecgis 는 AdminLoginInterceptor에서 AUTHZ='01'(SYSTEM) 또는
 * '07'(SUPER)만 허용. 테스트 계정은 AUTHZ='02'(일반 관리자)이므로 POST 요청은 403 반환.
 * GET /ajax, DELETE /{seq} 는 인터셉터 패턴에 매칭되지 않아 정상 동작.
 */
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class AdminEcgiBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-ecgi-teardown.sql", AdminEcgiBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-ecgi-setup.sql", AdminEcgiBlackBoxTest.class);
        // ECGI 컬럼을 LocalStack KMS(CMK-1)로 암호화 — 서버가 응답 시 decrypt하므로 필수
        TestUtil.encryptEcgi(dbConnection, 97301, "1234567890");
        sessionId = TestUtil.adminLogin(BASE_URL, "ecgiadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-ecgi-teardown.sql", AdminEcgiBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== GET /ajax — 목록 조회 ====================

    @Test @Order(1)
    void NTC_ecgiList() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("length", 10).queryParam("start", 0)
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(200)
            .body("iTotalRecords", equalTo(1))
            .body("aaData[0].ecgi", equalTo("1234567890"))
            .body("aaData[0].name", equalTo("TestEcgi"))
            .body("aaData[0].location", equalTo("TestLocation"));
    }

    // ==================== POST / — ECGI 등록 (403 Forbidden for AUTHZ='02') ====================

    @Test @Order(2)
    void ATC_createEcgi_forbidden() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("location", "NewLocation")
            .formParam("name", "NewEcgi")
            .formParam("ecgi", "9876543210")
        .when().post("/web/admin/ecgis")
        .then().log().all().statusCode(403);
    }

    // ==================== ATC — 중복 ECGI 등록도 403 (인터셉터에서 차단) ====================

    @Test @Order(3)
    void ATC_createEcgi_duplicate_forbidden() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("location", "DupLocation")
            .formParam("name", "DupEcgi")
            .formParam("ecgi", "1234567890")
        .when().post("/web/admin/ecgis")
        .then().log().all().statusCode(403);
    }

    // ==================== DELETE /{ecgiSeqs} — ECGI 삭제 ====================

    @Test @Order(4)
    void NTC_removeEcgi() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().delete("/web/admin/ecgis/97301")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    // ==================== VTC — XSS도 403 (인터셉터에서 차단) ====================

    @Test @Order(5)
    void ATC_createEcgi_xss_forbidden() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("location", "<script>alert(1)</script>")
            .formParam("name", "Test")
            .formParam("ecgi", "1111111111")
        .when().post("/web/admin/ecgis")
        .then().log().all().statusCode(403);
    }

    // ==================== ATC — 인증 없이 접근 ====================

    @Test @Order(6)
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(401);
    }
}

