package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import io.restassured.http.ContentType;

/**
 * @target-controller APIClientController
 * @target-api POST /api/clients/{clientSeq}/auth
 * Test Plan: .nimbus/artifacts/test-plan/APIClientService_getAuth.md (NTC 1, VTC 2, ATC 13)
 *
 * 인터셉터: /auth 경로는 token 검증 스킵 (uri.indexOf("/auth") == -1 조건)
 *   단, clientSeq 숫자 검증 + getClientNameAndTemplate 호출은 수행
 * 외부 연동: NcasAuth → NcasHttpConnection → URL.openConnection (ngCAS 인증)
 *   → WireMock으로 stub (ncas.url 프로퍼티를 WireMock 주소로 오버라이드)
 * Controller 검증: ecgi ^[0-9]{1,10}$, imei ^[0-9]{1,14}$, gcmToken ^[a-zA-Z0-9\-\%\_]{1,256}$
 *   controlledByUser: "true"/"false" only
 */
class ClientsAuthBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
    }

    @AfterAll
    static void cleanup() throws Exception {
        if (dbConnection != null) dbConnection.close();
    }

    @BeforeEach
    void beforeEach() {
        // Reset Docker WireMock via Admin API
        io.restassured.RestAssured.given().baseUri("http://localhost:9090").post("/__admin/reset");
        // Load stub mappings (token first with higher priority)
        loadStubToDocker("wiremock/ncas-token-success.json");
        loadStubToDocker("wiremock/clients-auth-ncas-success.json");
        TestUtil.executeSql(dbConnection, "sql/clients-auth-teardown.sql", ClientsAuthBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/clients-auth-setup.sql", ClientsAuthBlackBoxTest.class);
        // KMS 암호화 — getAuth에서 CTN 복호화 + NCAS 인증까지 도달하기 위해 필요
        TestUtil.encryptMemberCtn(dbConnection, 90011, "01012345678");
        TestUtil.encryptEcgi(dbConnection, 90110, "1234567890");
        // NGCAS_TOKEN 준비 — 토큰 만료 방지 (EXPIRE_TIMER를 크게 설정)
        try (Statement stmt = dbConnection.createStatement()) {
            stmt.execute("DELETE FROM NGCAS_TOKEN WHERE TOKEN_ID = 1");
            stmt.execute("INSERT INTO NGCAS_TOKEN (TOKEN_ID, ACCESS_TOKEN, REFRESH_TOKEN, EXPIRE_TIMER, REG_TIME) VALUES (1, 'test_ncas_access_token', 'test_ncas_refresh_token', 86400, NOW())");
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    private void loadStubToDocker(String resourcePath) {
        String json = TestUtil.readResource(resourcePath, ClientsAuthBlackBoxTest.class);
        io.restassured.RestAssured.given()
            .baseUri("http://localhost:9090")
            .contentType("application/json")
            .body(json)
            .post("/__admin/mappings");
    }

    // ========== NTC ==========

    /** [NTC_branch_getAuth_15] Happy Path - 정상 인증 성공 (test 모드, ngCAS WireMock)
     *
     *  서버 동작: getAuth는 정상 처리 시 err="000" + isCorporation/connectToPrivateApn/vipYn 등 반환.
     *  단 deviceModel 헤더가 없으면 imeiAuthPassDevices 비교에서 NPE 발생 (서버 버그, dev-fix-request §추가).
     *  본 테스트는 deviceModel을 명시하여 정상 경로 검증.
     */
    @Test
    void NTC_branch_getAuth_15() {
        given().log().all().baseUri(BASE_URL)
            .contentType(ContentType.JSON)
            .header("deviceModel", "SM-G998N")
            .body("{\"ctn\":\"01012345678\",\"iccid\":\"1234567890123456789\",\"ecgi\":\"1234567890\",\"controlledByUser\":\"true\"}")
        .when().post("/api/clients/9011/auth")
