// =========================================================================
// AWS Encryption SDK 기반 ACCESS_TOKEN 암호화 유틸리티 (CMK-4)
// =========================================================================

private static com.amazonaws.encryptionsdk.AwsCrypto awsCryptoToken;
private static com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager cachingCmmToken;

/**
 * AWS Encryption SDK를 사용하여 클라이언트 ACCESS_TOKEN 페이로드를 암호화한다.
 * 서버의 tokenEncryptionService (CMK-4)와 동일한 방식 (Envelope Encryption + Base64).
 * ClientLoginInterceptor가 Authorization: Bearer 헤더로 받은 값을 복호화하여
 * {tokenType, expiredAt, memberSeq, clientSeq} 페이로드를 검증한다.
 *
 * @param plaintextJson 토큰 페이로드 JSON 평문
 * @return Base64 인코딩된 암호문 (서버가 복호화 가능)
 */
static synchronized String kmsEncryptToken(String plaintextJson) {
    if (plaintextJson == null || plaintextJson.isEmpty()) return "";
    initKmsTokenIfNeeded();
    try {
        com.amazonaws.encryptionsdk.CryptoResult<byte[], ?> result =
            awsCryptoToken.encryptData(cachingCmmToken,
                plaintextJson.getBytes(java.nio.charset.StandardCharsets.UTF_8),
                java.util.Collections.emptyMap());
        return java.util.Base64.getEncoder().encodeToString(result.getResult());
    } catch (Exception e) {
        throw new RuntimeException("KMS token encrypt failed", e);
    }
}

/**
 * 유효한 클라이언트 ACCESS_TOKEN(Bearer 값)을 생성한다.
 * expiredAt은 현재+1일(yyyyMMddHHmmss)로 설정하여 만료를 회피한다.
 */
static String buildClientAccessToken(long memberSeq, long clientSeq) {
    String expiredAt = java.time.LocalDateTime.now().plusDays(1)
        .format(java.time.format.DateTimeFormatter.ofPattern("yyyyMMddHHmmss"));
    String payload = String.format(
        "{\"tokenType\":\"ACCESS\",\"expiredAt\":\"%s\",\"memberSeq\":%d,\"clientSeq\":%d}",
        expiredAt, memberSeq, clientSeq);
    return kmsEncryptToken(payload);
}

@SuppressWarnings("deprecation")
private static void initKmsTokenIfNeeded() {
    if (awsCryptoToken != null) return;

    String endpoint = System.getProperty("test.localstack.endpoint", "http://localhost:4566");
    String region = System.getProperty("test.aws.region", "ap-northeast-2");
    String keyAlias = "alias/cmk-4-pltelapne2"; // tokenEncryptionService용 CMK

    awsCryptoToken = com.amazonaws.encryptionsdk.AwsCrypto.builder()
        .withCommitmentPolicy(com.amazonaws.encryptionsdk.CommitmentPolicy.RequireEncryptRequireDecrypt)
        .build();

    software.amazon.awssdk.services.kms.KmsClient kmsClient =
        software.amazon.awssdk.services.kms.KmsClient.builder()
            .region(software.amazon.awssdk.regions.Region.of(region))
            .endpointOverride(java.net.URI.create(endpoint))
            .credentialsProvider(software.amazon.awssdk.auth.credentials.StaticCredentialsProvider.create(
                software.amazon.awssdk.auth.credentials.AwsBasicCredentials.create("test", "test")))
            .build();

    String keyArn = kmsClient.describeKey(
        software.amazon.awssdk.services.kms.model.DescribeKeyRequest.builder()
            .keyId(keyAlias).build()
    ).keyMetadata().arn();

    com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider provider =
        com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider.builder()
            .defaultRegion(software.amazon.awssdk.regions.Region.of(region))
            .customRegionalClientSupplier(r -> kmsClient)
            .buildStrict(keyArn);

    com.amazonaws.encryptionsdk.caching.CryptoMaterialsCache cache =
        new com.amazonaws.encryptionsdk.caching.LocalCryptoMaterialsCache(100);
    cachingCmmToken = com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager.newBuilder()
        .withMasterKeyProvider(provider)
        .withCache(cache)
        .withMaxAge(5, java.util.concurrent.TimeUnit.MINUTES)
        .withMessageUseLimit(1000)
        .build();
}

