package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ECGIController (src/main/java/com/ahope/ds/web/admin/ecgi/controller/ECGIController.java)
 * @target-api GET /web/admin/ecgis/ajax (ecgiList)
 *
 * 인증: 세션 (일반 관리자 AUTHZ='02'). ecgiList는 loginClientSeq 스코프로 조회.
 * 외부 연동: 없음 (DB 조회 + KMS(CMK-1) 복호화만). WireMock 미적용.
 */
class AdminEcgisAjaxBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-ecgis-ajax-teardown.sql", AdminEcgisAjaxBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-ecgis-ajax-setup.sql", AdminEcgisAjaxBlackBoxTest.class);
        // ECGI 컬럼을 LocalStack KMS(CMK-1)로 암호화 — 서버가 응답 시 decrypt하므로 필수
        TestUtil.encryptEcgi(dbConnection, 96040, "9988776655");
        sessionId = TestUtil.adminLogin(BASE_URL, "ecgiajaxadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-ecgis-ajax-teardown.sql", AdminEcgisAjaxBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== NTC ====================

    /** [NTC_ecgiList_default] 기본 페이징 조회 — setup 1건이 정확히 반환 */
    @Test
    void NTC_ecgiList_default() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("start", 0).queryParam("length", 10)
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(200)
            .body("iTotalRecords", equalTo(1))
            .body("aaData[0].ecgi", equalTo("9988776655"))
            .body("aaData[0].name", equalTo("AjaxEcgi"))
            .body("aaData[0].location", equalTo("AjaxLocation"));
    }

    /** [NTC_ecgiList_search] 이름 검색어 매칭 — 동일 1건 반환 */
    @Test
    void NTC_ecgiList_searchMatch() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("start", 0).queryParam("length", 10)
            .queryParam("searchValue", "AjaxEcgi")
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(200)
            .body("iTotalRecords", equalTo(1))
            .body("aaData[0].name", equalTo("AjaxEcgi"));
    }

    /** [NTC_ecgiList_paging_beyond] length=0 페이징 경계 — 목록 데이터 없음, 총계는 유지 */
    @Test
    void NTC_ecgiList_pagingBeyond() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("start", 10).queryParam("length", 10)
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(200)
            .body("iTotalRecords", equalTo(1))
            .body("aaData.size()", equalTo(0));
    }

    // ==================== ATC ====================

    /** [ATC_noSession] 세션 없이 접근 → 401 */
    @Test
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(401);
    }
}

