import java.sql.ResultSet;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test
 *
 * @target-controller QuotaController (src/main/java/com/ahope/ds/web/admin/quota/controller/QuotaController.java)
 * @target-api DELETE /web/admin/quota/groups (deleteGroup)
 *   NOTE: 클래스 매핑 "/web/admin/quota" + 메서드 "groups" → "/web/admin/quota/groups".
 *
 * 인증: 세션 (일반 관리자 AUTHZ='02', 단 loginQuotaOnOff='01' 필요 → QUOTA_ONOFF='01').
 * 요청: memberGroupSeqs[] (long[]).
 * 외부 연동: 없음 (DB 조작만). WireMock 미적용.
 */
class AdminQuotaGroupsDeleteBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-quota-groups-delete-teardown.sql", AdminQuotaGroupsDeleteBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-quota-groups-delete-setup.sql", AdminQuotaGroupsDeleteBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "quotadeladmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-quota-groups-delete-teardown.sql", AdminQuotaGroupsDeleteBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    @BeforeEach
    void reseedGroup() {
        // 각 테스트 전에 삭제 대상 그룹을 재삽입 (멱등)
        try (java.sql.Statement stmt = dbConnection.createStatement()) {
            stmt.execute("DELETE FROM MEMBER_GROUP WHERE MEMBER_GROUP_SEQ IN (96070, 96071)");
            stmt.execute("INSERT INTO MEMBER_GROUP (MEMBER_GROUP_SEQ, CLIENT_SEQ, GROUP_NAME, QUOTA_NEXT, REG_TIME) "
                + "VALUES (96070, 96070, 'TestQuotaDelGroup', 500, NOW())");
            stmt.execute("INSERT INTO MEMBER_GROUP (MEMBER_GROUP_SEQ, CLIENT_SEQ, GROUP_NAME, QUOTA_NEXT, REG_TIME) "
                + "VALUES (96071, 96070, 'TestQuotaDelGroup2', 300, NOW())");
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    private int countGroup(long seq) throws Exception {
        try (PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT COUNT(*) FROM MEMBER_GROUP WHERE MEMBER_GROUP_SEQ = ?")) {
            ps.setLong(1, seq);
            ResultSet rs = ps.executeQuery();
            rs.next();
            return rs.getInt(1);
        }
    }

    // ==================== NTC ====================

    /** [NTC_deleteGroup_single] 그룹 1건 삭제 → err=000, DB에서 실제 삭제 확인 */
    @Test
    void NTC_deleteGroup_single() throws Exception {
        Assertions.assertEquals(1, countGroup(96070));
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 96070)
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
        Assertions.assertEquals(0, countGroup(96070));
    }

    /** [NTC_deleteGroup_multiple] 여러 그룹 동시 삭제 → err=000, 둘 다 삭제 */
    @Test
    void NTC_deleteGroup_multiple() throws Exception {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 96070)
            .queryParam("memberGroupSeqs[]", 96071)
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
        Assertions.assertEquals(0, countGroup(96070));
        Assertions.assertEquals(0, countGroup(96071));
    }

    /** [NTC_deleteGroup_nonexistent] 존재하지 않는 그룹 삭제 요청 → err=000 (영향 0건, 예외 없음) */
    @Test
    void NTC_deleteGroup_nonexistent() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 96099)
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    // ==================== VTC ====================

    /** [VTC_memberGroupSeqs_missing] 필수 파라미터 memberGroupSeqs[] 누락 → 400 Bad Request */
    @Test
    void VTC_memberGroupSeqs_missing() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(400);
    }

    /** [VTC_memberGroupSeqs_nonNumeric] 숫자가 아닌 값 → 400 (long[] 바인딩 실패) */
    @Test
    void VTC_memberGroupSeqs_nonNumeric() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", "abc")
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(400);
    }

    // ==================== ATC ====================

    /** [ATC_noSession] 세션 없이 접근 → 401 */
    @Test
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("memberGroupSeqs[]", 96070)
        .when().delete("/web/admin/quota/groups")
        .then().log().all().statusCode(401);
    }
}

