package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test
 *
 * @target-controller CryptoController (src/main/java/com/ahope/ds/web/superadmin/crypto/controller/CryptoController.java)
 * @target-api POST /web/super/admin/crypto/personal (getPersonalDecryption)
 *
 * 인증: 세션 (시스템 관리자 AUTHZ='07' — SuperAdminLoginInterceptor 통과).
 * 서비스: dataEncryptionService(CMK-2).decrypt(cryptoContent). 실패 시 err="115"(RuntimeException) / "001"(그 외).
 * 외부 연동: 없음 (KMS는 LocalStack SDK 경유). WireMock 미적용.
 */
class SuperadminCryptoPersonalBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/superadmin-crypto-personal-teardown.sql", SuperadminCryptoPersonalBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/superadmin-crypto-personal-setup.sql", SuperadminCryptoPersonalBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "cryptoprsnadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/superadmin-crypto-personal-teardown.sql", SuperadminCryptoPersonalBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== NTC ====================

    /** [NTC_decrypt_ctn] CMK-2로 암호화한 CTN을 복호화 → 원문 일치 */
    @Test
    void NTC_decrypt_ctn() {
        String plain = "01012345678";
        String cipher = TestUtil.kmsEncrypt(plain); // 서버의 dataEncryptionService와 동일 CMK-2
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", cipher)
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo(plain));
    }

    /** [NTC_decrypt_name] 한글 개인정보 원문 복호화 → 원문 일치 */
    @Test
    void NTC_decrypt_name() {
        String plain = "홍길동";
        String cipher = TestUtil.kmsEncrypt(plain);
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", cipher)
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo(plain));
    }

    /** [NTC_decrypt_withSurroundingSpace] 앞뒤 공백 포함 암호문 → 서버가 trim 후 복호화 → 원문 일치 */
    @Test
    void NTC_decrypt_withSurroundingSpace() {
        String plain = "01099998888";
        String cipher = TestUtil.kmsEncrypt(plain);
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", " " + cipher + " ")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo(plain));
    }

    // ==================== VTC ====================

    /** [VTC_cryptoContent_INVALID_FORMAT] 유효하지 않은 암호문 → err="115" */
    @Test
    void VTC_cryptoContent_invalidCiphertext() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", "not-a-valid-ciphertext")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("115"));
    }

    /** [VTC_cryptoContent_SPECIAL_CHAR] SQL/특수문자 암호문 → 복호화 불가 → err="115" */
    @Test
    void VTC_cryptoContent_specialChar() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", "'; DROP TABLE MEMBER--")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("115"));
    }

    // ==================== ATC ====================

    /** [ATC_noSession] 세션 없이 접근 → 401 (SuperAdminLoginInterceptor) */
    @Test
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", "anything")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(401);
    }
}

