 *
 * @target-controller TrafficController (src/main/java/com/ahope/ds/web/admin/traffic/controller/TrafficController.java)
 * @target-api POST /web/admin/traffic/excel/make (makeTrafficExcel)
 *   NOTE: 클래스 매핑 "/web/admin/traffic" + 메서드 "excel/make" → "/web/admin/traffic/excel/make".
 *
 * 인증/인가: AdminLoginInterceptor — /traffic/excel/make 는 Authz.SYSTEM('07')만 허용.
 *   AUTHZ='02'(일반 관리자)는 403.
 * 로직: excelReason 취약성 검사 → 통과 시 service.makeTrafficExcel (엑셀 생성 비동기) → err="000".
 * 외부 연동: 없음 (DB + S3(LocalStack)). WireMock 미적용.
 */
class AdminTrafficExcelMakeBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String systemSessionId; // AUTHZ='07'
    private static String normalSessionId; // AUTHZ='02'

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-traffic-excel-make-teardown.sql", AdminTrafficExcelMakeBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-traffic-excel-make-setup.sql", AdminTrafficExcelMakeBlackBoxTest.class);
        systemSessionId = TestUtil.adminLogin(BASE_URL, "trafficexceladmin", "testpw", dbConnection);
        normalSessionId = TestUtil.adminLogin(BASE_URL, "trafficexcelnormal", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-traffic-excel-make-teardown.sql", AdminTrafficExcelMakeBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    private static io.restassured.specification.RequestSpecification makeReq(String session, String searchDataType, String excelReason) {
        return given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", session)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("memberSeq", "96080")
            .formParam("searchType", "CTN")
            .formParam("searchValue", "")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("searchDataType", searchDataType)
            .formParam("excelReason", excelReason);
    }

    // ==================== NTC (시스템 관리자 '07') ====================

    /** [NTC_makeExcel_calculate] 정산(CALCULATE) 엑셀 생성 요청 → err="000" */
    @Test
    void NTC_makeExcel_calculate() {
        makeReq(systemSessionId, "CALCULATE", "정산 트래픽 엑셀 다운로드")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    /** [NTC_makeExcel_realtime] 실시간(REAL_TIME) 엑셀 생성 요청 → err="000" */
    @Test
    void NTC_makeExcel_realtime() {
        makeReq(systemSessionId, "REAL_TIME", "실시간 트래픽 엑셀 다운로드")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    /** [NTC_makeExcel_dailyPeriod] 일별(SEARCH_FOR_DAY) 조회 엑셀 생성 → err="000" */
    @Test
    void NTC_makeExcel_dailyPeriod() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", systemSessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("memberSeq", "96080")
            .formParam("searchType", "CTN")
            .formParam("searchValue", "")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchPeriodType", "SEARCH_FOR_DAY")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260302")
            .formParam("searchDataType", "REAL_TIME")
            .formParam("excelReason", "일별 트래픽 다운로드")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    // ==================== VTC (시스템 관리자 '07') ====================

    /** [VTC_excelReason_SPECIAL_CHAR] excelReason XSS → VULNERABLE_VALUE err="002" */
    @Test
    void VTC_excelReason_xss() {
        makeReq(systemSessionId, "CALCULATE", "<script>alert(1)</script>")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(200)
            .body("err", equalTo("002"));
    }

    // ==================== ATC ====================

    /** [ATC_makeExcel_forbidden] 일반 관리자('02')는 SYSTEM 전용 엔드포인트 접근 불가 → 403 */
    @Test
    void ATC_makeExcel_forbidden() {
        makeReq(normalSessionId, "CALCULATE", "권한 없는 다운로드")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(403);
    }

    /** [ATC_noSession] 세션 없이 접근 → 401 */
    @Test
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("searchDataType", "CALCULATE")
            .formParam("excelReason", "test")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(401);
    }
}

