import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ClientController (src/main/java/com/ahope/ds/web/superadmin/client/controller/ClientController.java)
 * @target-api PUT /web/super/admin/clients/{clientSeq}/cancel (modifyClientCancel)
 *
 * 인증: 세션 (시스템 관리자 AUTHZ='07').
 * 로직: LPS 가입 가입자 존재 시 err="001". 고객사 CANCEL_STATUS='01'(가입) → '02'(해지요청)로 UPDATE.
 *       그 외 상태(예:'02')는 분기 미해당 → 무변경 err="000".
 * 외부 연동: 없음 (DB 조작만). WireMock 미적용.
 */
class SuperadminClientCancelBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final long CLIENT_SEQ = 96020;
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/superadmin-client-cancel-teardown.sql", SuperadminClientCancelBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/superadmin-client-cancel-setup.sql", SuperadminClientCancelBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "clientcanceladmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/superadmin-client-cancel-teardown.sql", SuperadminClientCancelBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    @BeforeEach
    void resetCancelStatus() throws Exception {
        try (PreparedStatement ps = dbConnection.prepareStatement(
                "UPDATE CLIENT SET CANCEL_STATUS = '01' WHERE CLIENT_SEQ = ?")) {
            ps.setLong(1, CLIENT_SEQ);
            ps.executeUpdate();
        }
    }

    private String cancelStatus() throws Exception {
        try (PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT CANCEL_STATUS FROM CLIENT WHERE CLIENT_SEQ = ?")) {
            ps.setLong(1, CLIENT_SEQ);
            ResultSet rs = ps.executeQuery();
            rs.next();
            return rs.getString(1);
        }
    }

    // ==================== NTC ====================

    /** [NTC_cancelClient] 가입(01) 고객사 해지 요청 → err="000", CANCEL_STATUS='02' */
    @Test
    void NTC_cancelClient() throws Exception {
        Assertions.assertEquals("01", cancelStatus());
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/" + CLIENT_SEQ + "/cancel")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
        Assertions.assertEquals("02", cancelStatus());
    }

    /** [NTC_cancelClient_idempotentSecondCall] 이미 해지요청('02') 상태에서 재요청 → err="000", 상태 무변경('02') */
    @Test
    void NTC_cancelClient_idempotentSecondCall() throws Exception {
        // 1차 해지요청 (01 → 02)
        given().baseUri(BASE_URL).cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/" + CLIENT_SEQ + "/cancel")
        .then().statusCode(200).body("err", equalTo("000"));
        Assertions.assertEquals("02", cancelStatus());

        // 2차 요청 — '02'는 분기 미해당 → 무변경
        given().log().all().baseUri(BASE_URL).cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/" + CLIENT_SEQ + "/cancel")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
        Assertions.assertEquals("02", cancelStatus());
    }

    // ==================== ATC ====================

    /** [ATC_noSession] 세션 없이 접근 → 401 (SuperAdminLoginInterceptor) */
    @Test
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/" + CLIENT_SEQ + "/cancel")
        .then().log().all().statusCode(401);
    }
}

