package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import io.restassured.specification.RequestSpecification;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ClientAPIController (src/main/java/com/ahope/ds/client/controller/ClientAPIController.java)
 * @target-api GET /client/sync (sync)
 *
 * 인증: ClientLoginInterceptor — Authorization: Bearer {ACCESS_TOKEN}.
 *   토큰은 tokenEncryptionService(CMK-4)로 암호화된 JSON {tokenType:"ACCESS", expiredAt, memberSeq, clientSeq}.
 *   실패 코드: 816(누락) / 812(복호화·형식오류) / 855(타입불일치) / 802(만료).
 * 응답: ClientResultMap {code:"200", message:"OK", data:{...}}.
 * 외부 연동: 없음 (KMS는 LocalStack SDK 경유, DB 조회). WireMock 미적용.
 */
class ClientSyncBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final DateTimeFormatter TOKEN_DF = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
    private static final long CLIENT_SEQ = 96010;
    private static final long MEMBER_SEQ = 96010;
    private static Connection dbConnection;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/client-sync-setup.sql", ClientSyncBlackBoxTest.class);
        // 허용 ECGI를 LocalStack KMS(CMK-1)로 암호화 — 서버가 sync 응답 시 decrypt
        TestUtil.encryptEcgi(dbConnection, 96010, "1234500001");
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    /** 단말 필수 헤더 부착 */
    private static RequestSpecification withDeviceHeaders(RequestSpecification spec) {
        return spec
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01");
    }

    // ==================== NTC ====================

    /** [NTC_sync_success] 유효 토큰 → code=200 + client-scoped data 정확 검증 */
    @Test
    void NTC_sync_success() {
        String token = TestUtil.buildClientAccessToken(MEMBER_SEQ, CLIENT_SEQ);
        withDeviceHeaders(given().log().all().baseUri(BASE_URL))
            .header("Authorization", "Bearer " + token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("200"))
            .body("message", equalTo("OK"))
            .body("data.mainBackgroundImageUrl", equalTo("https://cdn.test/bg_96010.png"))
            .body("data.interlockingAppVersion", equalTo("02.00.01"))
            .body("data.interlockingAppList.size()", equalTo(1))
            .body("data.interlockingAppList[0].appName", equalTo("TestApp"))
            .body("data.interlockingAppList[0].packageName", equalTo("com.test.app"))
            .body("data.allowedEcgiList.size()", equalTo(1))
            .body("data.allowedEcgiList[0]", equalTo("1234500001"))
            .body("data.solutionList.size()", equalTo(1))
            .body("data.solutionList[0].solutionId", equalTo(96010))
            .body("data.solutionList[0].solutionName", equalTo("TestSolution"))
            .body("data.solutionList[0].enabled", equalTo(true));
    }

    /** [NTC_sync_solutionBanned] 솔루션 금지(MEMBER_BAN_SOLN_PKG) 등록 시 enabled=false */
    @Test
    void NTC_sync_solutionBanned() throws Exception {
        // 금지 등록 → enabled=false, 종료 후 제거
        try (java.sql.Statement stmt = dbConnection.createStatement()) {
            stmt.execute("INSERT INTO MEMBER_BAN_SOLN_PKG (MEMBER_SEQ, CLIENT_SEQ, SOLN_SEQ) VALUES (96010, 96010, 96010)");
        }
        try {
            String token = TestUtil.buildClientAccessToken(MEMBER_SEQ, CLIENT_SEQ);
            withDeviceHeaders(given().log().all().baseUri(BASE_URL))
                .header("Authorization", "Bearer " + token)
            .when().get("/client/sync")
            .then().log().all().statusCode(200)
                .body("code", equalTo("200"))
                .body("data.solutionList[0].solutionId", equalTo(96010))
                .body("data.solutionList[0].enabled", equalTo(false));
        } finally {
            try (java.sql.Statement stmt = dbConnection.createStatement()) {
                stmt.execute("DELETE FROM MEMBER_BAN_SOLN_PKG WHERE MEMBER_SEQ = 96010 AND CLIENT_SEQ = 96010 AND SOLN_SEQ = 96010");
            }
        }
    }

    /** [NTC_sync_dataEnvelope] 정상 응답의 data 봉투 구조(허용 ECGI 값) 재검증 */
    @Test
    void NTC_sync_dataEnvelope() {
        String token = TestUtil.buildClientAccessToken(MEMBER_SEQ, CLIENT_SEQ);
        withDeviceHeaders(given().log().all().baseUri(BASE_URL))
            .header("Authorization", "Bearer " + token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("200"))
            .body("data.interlockingAppVersion", equalTo("02.00.01"))
            .body("data.allowedEcgiList[0]", equalTo("1234500001"));
    }

    // ==================== ATC (인증 실패) ====================

    /** [ATC_missingToken] Authorization 헤더 누락 → code="816" */
    @Test
    void ATC_missingToken() {
        withDeviceHeaders(given().log().all().baseUri(BASE_URL))
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("816"));
    }

    /** [ATC_notBearer] Bearer 접두사 없는 토큰 → code="812" */
    @Test
    void ATC_notBearer() {
        withDeviceHeaders(given().log().all().baseUri(BASE_URL))
            .header("Authorization", "Token abcdef")
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("812"));
    }

    /** [ATC_invalidToken] 복호화 불가한 토큰 값 → code="812" */
    @Test
    void ATC_invalidToken() {
        withDeviceHeaders(given().log().all().baseUri(BASE_URL))
            .header("Authorization", "Bearer not-a-valid-token")
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("812"));
    }

    /** [ATC_wrongTokenType] tokenType이 ACCESS가 아님(REFRESH) → code="855" */
    @Test
    void ATC_wrongTokenType() {
        String expiredAt = LocalDateTime.now().plusDays(1).format(TOKEN_DF);
        String payload = String.format(
            "{\"tokenType\":\"REFRESH\",\"expiredAt\":\"%s\",\"memberSeq\":%d,\"clientSeq\":%d}",
            expiredAt, MEMBER_SEQ, CLIENT_SEQ);
        String token = TestUtil.kmsEncryptToken(payload);
        withDeviceHeaders(given().log().all().baseUri(BASE_URL))
            .header("Authorization", "Bearer " + token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("855"));
    }

    /** [ATC_expiredToken] expiredAt이 과거 → code="802" */
    @Test
    void ATC_expiredToken() {
        String payload = String.format(
            "{\"tokenType\":\"ACCESS\",\"expiredAt\":\"20200101000000\",\"memberSeq\":%d,\"clientSeq\":%d}",
            MEMBER_SEQ, CLIENT_SEQ);
        String token = TestUtil.kmsEncryptToken(payload);
        withDeviceHeaders(given().log().all().baseUri(BASE_URL))
            .header("Authorization", "Bearer " + token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("802"));
    }
}

